create temp table website_results(name text primary key);grant select,insert on website_results to anon,authenticated,service_role;
create function pg_temp.ok(v boolean,label text) returns void language plpgsql as $$begin if v is distinct from true then raise exception 'FAILED %',label;end if;insert into pg_temp.website_results values(label);end$$;
create function pg_temp.denied(sql text,code text,label text) returns void language plpgsql as $$declare caught text;msg text;begin begin execute sql;exception when others then get stacked diagnostics caught=returned_sqlstate,msg=message_text;end;if caught is distinct from code then raise exception 'FAILED % expected % got % (%)',label,code,caught,msg;end if;insert into pg_temp.website_results values(label);end$$;
create function pg_temp.claim(n integer) returns void language sql as $$select set_config('request.jwt.claims',jsonb_build_object('iss','https://gmvouqgjbtbkbhrdruzu.supabase.co/auth/v1','aud','authenticated','role','authenticated','sub','10000000-0000-0000-0000-'||lpad(n::text,12,'0'))::text,true)::void$$;
